-- ============================================================================
-- B5 FOLLOW-ON W2 (publish inputs in prompts and lessons): cementing.
--
-- Plan of record: docs/graded-field-audit/FOLLOW-ON-PROGRAMME.md section 1,
-- route (a), and the spec docs/graded-field-audit/w2/cementing.json (the
-- inputs, where each came from, and the key each reproduces through the
-- vendored engines). Owner approved D1 to D7 as recommended, 2026-09-21.
--
-- ADVANCED
--   Prompt only, no field moves. Fields 1 and 3 need the mid-span sag, which
--   needs E x I of the 9-5/8 inch casing; the lessons give E x I only as a
--   number for 7 inch casing and never E or the I formula, and E = 200 or 207
--   GPa moves the answer by 1e-3 or 3e-5 against tol 5e-7 (B5 finding 1). The
--   prompt now states E x I (vendored stringProperties) and how it is built, so
--   both are hand work from m02 l04 and m03 l01. Keys, expected values and
--   tolerances are unchanged.
--   PROMPT was: on the same slant trajectory.
--   PROMPT now: on the same slant trajectory. Its bending stiffness E x I is
--   12266792.85346564 N m2, which is E = 206.8 GPa on I = pi/64 (OD^4 - ID^4).
--
-- WHAT DOES NOT MOVE. `fields` (every key, label, unit, expected value and
-- tolerance), title, dataset, status and the row. The guard requires `fields`
-- to equal its live value exactly, before and after, so no answer grades
-- differently, nobody is re-scored and no attempts guard is needed.
--
-- GUARDS. Each row must hold EITHER its published prompt (by md5) with its
-- live fields (exact jsonb), as production holds it after W1 (it is
-- rewritten), OR its W2 prompt with the same fields (left alone). Anything
-- else raises and the whole file rolls back. A file that will write first
-- checks the W1 post-state and refuses without it. Generated by
-- docs/graded-field-audit/w2_capstones.py. SAFE TO RE-RUN: a second run
-- writes nothing.
-- ============================================================================

do $$
declare
  v_n        integer;
  v_count    integer;
  v_written  integer := 0;
  v_s0       text;
begin
  -- cementing / advanced
  select count(*) into v_n from public.academy_capstones where app_slug = 'cementing' and tier = 'advanced' and active;
  if v_n <> 1 then raise exception 'w2 cementing refused: cementing/advanced has % active capstone rows, expected 1', v_n; end if;
  select case when md5(prompt) = '7e7412057740dcb01936e298c2026745' and fields = '[{"key": "min_standoff", "tol": 5E-7, "unit": "-", "label": "Minimum standoff", "expected": 0.8556417628346304}, {"key": "standoff_at_centralizer_at_min", "tol": 5E-7, "unit": "-", "label": "Standoff at the centralizer", "expected": 0.8841171967314949}, {"key": "required_spacing_m", "tol": 5E-7, "unit": "m", "label": "Required spacing", "expected": 15.99770776601963}, {"key": "buoyed_weight_n_per_m", "tol": 0.0005, "unit": "N/m", "label": "Buoyed weight", "expected": 572.3226608514}, {"key": "min_standoff_rigid", "tol": 5E-7, "unit": "-", "label": "Minimum standoff, rigid", "expected": 0.6424096181525695}, {"key": "centralizer_spring_rate_n_per_m", "tol": 0.005, "unit": "N/m", "label": "Spring rate", "expected": 999875.0156230475}]'::jsonb then 'old'
              when md5(prompt) = '488183881de61760eb8292aaa0868100' and fields = '[{"key": "min_standoff", "tol": 5E-7, "unit": "-", "label": "Minimum standoff", "expected": 0.8556417628346304}, {"key": "standoff_at_centralizer_at_min", "tol": 5E-7, "unit": "-", "label": "Standoff at the centralizer", "expected": 0.8841171967314949}, {"key": "required_spacing_m", "tol": 5E-7, "unit": "m", "label": "Required spacing", "expected": 15.99770776601963}, {"key": "buoyed_weight_n_per_m", "tol": 0.0005, "unit": "N/m", "label": "Buoyed weight", "expected": 572.3226608514}, {"key": "min_standoff_rigid", "tol": 5E-7, "unit": "-", "label": "Minimum standoff, rigid", "expected": 0.6424096181525695}, {"key": "centralizer_spring_rate_n_per_m", "tol": 0.005, "unit": "N/m", "label": "Spring rate", "expected": 999875.0156230475}]'::jsonb then 'new'
              else 'other' end
    into v_s0 from public.academy_capstones where app_slug = 'cementing' and tier = 'advanced' and active;
  if v_s0 = 'other' then
    raise exception 'w2 cementing refused: cementing/advanced matches neither its published form (prompt md5 7e7412057740dcb01936e298c2026745) nor its W2 form (prompt md5 488183881de61760eb8292aaa0868100), with the fields this file was generated against';
  end if;

  -- nothing to write: every row is already in its W2 form
  if v_s0 = 'new' then
    raise notice 'w2 cementing: 0 of 1 row(s) written, all already applied';
    return;
  end if;

  -- W1 (20261024a/b) must be applied first: production holds it, and the W2
  -- apply script checks all 34 files; this reads two of its rows
  if exists (select 1 from public.academy_capstones where app_slug = 'integrity' and tier = 'beginner' and active and md5(prompt) <> '0e0ac66d6b97e9f7f66b5055e1fddf7d')
     or exists (select 1 from public.academy_capstones where app_slug = 'welldata' and tier = 'beginner' and active and md5(prompt) <> 'f362ed27e7d8766e7e51dcf1ca0e5e6e') then
    raise exception 'w2 cementing refused: W1 (20261024*) is not applied on this database; apply it first (/root/w1-apply/apply.sh apply --prod)';
  end if;

  if v_s0 = 'old' then
    update public.academy_capstones
       set prompt = 'Six centralization numbers for the Associate capstone''s string. The casing is 9-5/8 inch at 0.244475 m outside and 0.2204974 inside, weighing 69.9437033 kg per metre, on the same slant trajectory. Its bending stiffness E x I is 12266792.85346564 N m2, which is E = 206.8 GPa on I = pi/64 (OD^4 - ID^4). The hole is cased to 350 m at 0.315341 m and open hole to 1400 at 0.31115. The centralizer is a BOW SPRING at 10.5 m spacing with a restoring force of 11000 N quoted at the standard 0.67. The mud is 1300 kg/m3, not the lessons'' 1440. A RIGID blade of 0.29 m is to be evaluated on the same string at the same spacing. Report: (1) the MINIMUM STANDOFF with the bow springs; (2) the STANDOFF AT THE CENTRALIZER at the interval where that minimum occurs; (3) the REQUIRED SPACING to reach the API target, in metres; (4) the BUOYED WEIGHT per metre at 1300 kg/m3, in newtons per metre; (5) the MINIMUM STANDOFF with the 0.29 m RIGID blade at the same spacing; and (6) the SPRING RATE of the 11000 N bow spring in the open hole, in newtons per metre. Do field 4 first, then field 6, then 1 and 2 from one profile, then 3 by bisection, then 5, interval by interval. Traps. The 30 percent excess of the other two capstones appears NOWHERE here: standoffProfile runs the annulus at zero excess, so a clearance of about 0.042 rather than 0.033 means the wrong bore was used. The casing is 9-5/8 inch, so its clearance, its weight and its bending stiffness all differ from the lessons''. The mud is LIGHTER, so the casing is heavier in the hole and the standoff slightly worse. Field 5 is the smallest rigid standoff anywhere on the string, cased hole and open hole alike: in each interval the sag is subtracted from the blade ratio of that interval''s bore exactly as it is for a bow spring, and where the well is vertical the sag is zero. Free checks: field 1 must be at or below field 2; field 3 must EXCEED the 10.5 m being run, because the job passes; field 6 times 0.33 times the open hole clearance must give back 11000 N; and field 1 passes the API 67 percent while field 5 does not.'
     where app_slug = 'cementing' and tier = 'advanced' and active and md5(prompt) = '7e7412057740dcb01936e298c2026745';
    get diagnostics v_count = row_count;
    if v_count <> 1 then raise exception 'w2 cementing refused: cementing/advanced updated % rows', v_count; end if;
    v_written := v_written + 1;
  end if;
  if (select (md5(prompt) = '488183881de61760eb8292aaa0868100' and fields = '[{"key": "min_standoff", "tol": 5E-7, "unit": "-", "label": "Minimum standoff", "expected": 0.8556417628346304}, {"key": "standoff_at_centralizer_at_min", "tol": 5E-7, "unit": "-", "label": "Standoff at the centralizer", "expected": 0.8841171967314949}, {"key": "required_spacing_m", "tol": 5E-7, "unit": "m", "label": "Required spacing", "expected": 15.99770776601963}, {"key": "buoyed_weight_n_per_m", "tol": 0.0005, "unit": "N/m", "label": "Buoyed weight", "expected": 572.3226608514}, {"key": "min_standoff_rigid", "tol": 5E-7, "unit": "-", "label": "Minimum standoff, rigid", "expected": 0.6424096181525695}, {"key": "centralizer_spring_rate_n_per_m", "tol": 0.005, "unit": "N/m", "label": "Spring rate", "expected": 999875.0156230475}]'::jsonb) from public.academy_capstones where app_slug = 'cementing' and tier = 'advanced' and active) is not true then
    raise exception 'w2 cementing refused: cementing/advanced does not read back as its W2 form';
  end if;

  raise notice 'w2 cementing: % of 1 row(s) written, % already applied', v_written, 1 - v_written;
end $$;
